1	//! The field mapping: which parts of a record are its id, title, searchable
2	//! text, group, date, filters and display fields.
3	//!
4	//! Resolution order: `leviathan.toml` (or inference from the data when there
5	//! is no config), then CLI flags on top. The effective mapping is stored in
6	//! the index, so later queries, upserts and the MCP server all use exactly
7	//! the mapping the index was built with.
8	
9	use std::path::Path;
10	
11	use anyhow::{Context, Result, bail};
12	use serde::{Deserialize, Deserializer, Serialize};
13	
14	pub const DEFAULT_FILE: &str = "leviathan.toml";
15	
16	#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
17	#[serde(default, deny_unknown_fields)]
18	pub struct Config {
19	    pub about: About,
20	    pub source: SourceConfig,
21	    pub fields: Fields,
22	    pub rank: Rank,
23	    #[serde(skip_serializing_if = "MemoryConfig::is_default")]
24	    pub memory: MemoryConfig,
25	    /// Several kinds of record in one index, each with its own sources and
26	    /// mapping. When set, `source` and `fields` are unused.
27	    #[serde(skip_serializing_if = "Vec::is_empty")]
28	    pub kinds: Vec<KindConfig>,
29	}
30	
31	/// One kind of record (`[[kinds]]`): tickets, customers, orders. Its records
32	/// carry the filter `_kind = <name>` and ids of the form `<name>:<id>`.
33	#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
34	#[serde(default, deny_unknown_fields)]
35	pub struct KindConfig {
36	    /// Short name: letters, digits, `_` and `-`.
37	    pub name: String,
38	    /// Singular noun for one record of this kind.
39	    pub record: String,
40	    /// Singular noun for one group of this kind.
41	    pub group: String,
42	    /// Files of this kind (relative to the config file), or one table of a
43	    /// SQLite file as `path#table`.
44	    pub paths: Vec<String>,
45	    pub format: Format,
46	    /// Query for a SQLite source.
47	    pub sql: Option<String>,
48	    pub fields: Fields,
49	}
50	
51	impl Config {
52	    /// The mapping as it applies to one kind: that kind's fields and nouns,
53	    /// with the index-wide ranking.
54	    pub fn for_kind(&self, kind: &KindConfig) -> Config {
55	        Config {
56	            about: About {
57	                name: None,
58	                description: None,
59	                record: if kind.record.is_empty() { "record".into() } else { kind.record.clone() },
60	                group: if kind.group.is_empty() { "group".into() } else { kind.group.clone() },
61	            },
62	            source: SourceConfig { paths: kind.paths.clone(), format: kind.format, sql: kind.sql.clone() },
63	            fields: kind.fields.clone(),
64	            rank: self.rank.clone(),
65	            memory: Default::default(),
66	            kinds: Vec::new(),
67	        }
68	    }
69	}
70	
71	/// A kind name from free text: lowercase letters, digits, `_` and `-`.
72	pub fn kind_name(raw: &str) -> String {
73	    let mut out = String::new();
74	    for c in raw.trim().chars().flat_map(char::to_lowercase) {
75	        if c.is_alphanumeric() || c == '-' {
76	            out.push(c);
77	        } else if !out.ends_with('_') {
78	            out.push('_');
79	        }
80	    }
81	    let out = out.trim_matches('_').to_string();
82	    if out.is_empty() { "records".into() } else { out }
83	}
