85	/// The read/write memory store (`leviathan memory`, `--memory`). Separate
86	/// from the data index, which stays read-only.
87	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
88	#[serde(default, deny_unknown_fields)]
89	pub struct MemoryConfig {
90	    /// Memory database, relative to the config file
91	    /// [default: ~/.leviathan/memory.db].
92	    pub path: Option<String>,
93	    /// Namespace new memories are written to.
94	    pub namespace: String,
95	    /// Namespaces recall reads by default [default: just `namespace`].
96	    pub read: Vec<String>,
97	    /// Token budget for one recall.
98	    pub budget: usize,
99	    /// Token budget for the session-start briefing.
100	    pub briefing_budget: usize,
101	    /// Character cap for one memory.
102	    pub max_chars: usize,
103	    /// Recency half-life in days per kind; 0 means no decay.
104	    pub half_life: std::collections::BTreeMap<String, f64>,
105	    /// Subjects whose memories lead every briefing.
106	    pub pin: Vec<String>,
107	}
108	
109	impl Default for MemoryConfig {
110	    fn default() -> Self {
111	        Self {
112	            path: None,
113	            namespace: "default".into(),
114	            read: Vec::new(),
115	            budget: 800,
116	            briefing_budget: 600,
117	            max_chars: 400,
118	            half_life: Default::default(),
119	            pin: Vec::new(),
120	        }
121	    }
122	}
123	
124	impl MemoryConfig {
125	    fn is_default(&self) -> bool {
126	        self == &Self::default()
127	    }
128	}
