130	/// How results talk about the data: "3 tickets for customer acme".
131	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
132	#[serde(default, deny_unknown_fields)]
133	pub struct About {
134	    pub name: Option<String>,
135	    pub description: Option<String>,
136	    /// Singular noun for one record ("ticket", "log line", "incident").
137	    pub record: String,
138	    /// Singular noun for one group ("customer", "machine", "repo").
139	    pub group: String,
140	}
141	
142	impl Default for About {
143	    fn default() -> Self {
144	        Self { name: None, description: None, record: "record".into(), group: "group".into() }
145	    }
146	}
147	
148	#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
149	#[serde(default, deny_unknown_fields)]
150	pub struct SourceConfig {
151	    /// Files or directories, relative to the config file.
152	    pub paths: Vec<String>,
153	    pub format: Format,
154	    /// Query for SQLite sources (default: the database's only table).
155	    pub sql: Option<String>,
156	}
157	
158	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, clap::ValueEnum)]
159	#[serde(rename_all = "lowercase")]
160	pub enum Format {
161	    /// From the file extension; stdin is sniffed.
162	    #[default]
163	    Auto,
164	    Jsonl,
165	    Json,
166	    Csv,
167	    Tsv,
168	    Sqlite,
169	}
170	
171	/// Every field is a path into a record: `a.b` for nesting, `items[].name`
172	/// (or just `items.name`) for every element of an array.
173	#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
174	#[serde(default, deny_unknown_fields)]
175	pub struct Fields {
176	    /// Unique record id. Without one, records are numbered `<file>:<line>`
177	    /// and upserts cannot replace them.
178	    pub id: Option<String>,
179	    /// Short headline; the first path that is present wins.
180	    #[serde(deserialize_with = "one_or_many")]
181	    pub title: Vec<String>,
182	    /// Searched text. Empty means every string in the record.
183	    pub text: Vec<String>,
184	    /// Scope searches to one entity (customer, machine, repo, host, ...).
185	    pub group: Option<String>,
186	    /// Human name of the group, used to resolve "the filler on line 3".
187	    pub group_name: Option<String>,
188	    /// Recency for ranking ties, `recent`, and `--since/--until`. First
189	    /// present path wins.
190	    #[serde(deserialize_with = "one_or_many")]
191	    pub date: Vec<String>,
192	    /// Exact-match filters (`--where status=open`), counted in `describe`.
193	    pub filters: Vec<String>,
194	    /// Shown on every result card, in this order.
195	    pub display: Vec<String>,
196	    /// Placeholder values treated as missing ("n/a", "done", "-").
197	    pub empty_values: Vec<String>,
198	}
199	
200	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
201	#[serde(default, deny_unknown_fields)]
202	pub struct Rank {
203	    /// BM25 weight of title matches relative to body text.
204	    pub title_weight: f64,
205	    pub boost: Vec<Boost>,
206	}
207	
208	impl Default for Rank {
209	    fn default() -> Self {
210	        Self { title_weight: 2.0, boost: Vec::new() }
211	    }
212	}
213	
214	/// Multiply relevance by `1 + weight` for records where any of `field` is
215	/// present (non-empty, not a placeholder) or, with `equals`, has that value.
216	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
217	#[serde(deny_unknown_fields)]
218	pub struct Boost {
219	    #[serde(deserialize_with = "one_or_many")]
220	    pub field: Vec<String>,
221	    #[serde(default, skip_serializing_if = "Option::is_none")]
222	    pub equals: Option<String>,
223	    pub weight: f64,
224	}
225	
226	fn one_or_many<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<String>, D::Error> {
227	    #[derive(Deserialize)]
228	    #[serde(untagged)]
229	    enum OneOrMany {
230	        One(String),
231	        Many(Vec<String>),
232	    }
233	    Ok(match OneOrMany::deserialize(d)? {
234	        OneOrMany::One(s) => vec![s],
235	        OneOrMany::Many(v) => v,
236	    })
237	}
238	
239	impl Config {
240	    pub fn load(path: &Path) -> Result<Self> {
241	        let text = std::fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
242	        let mut cfg: Config = toml::from_str(&text).with_context(|| format!("parse {}", path.display()))?;
243	        if let Some(dir) = path.parent().filter(|d| !d.as_os_str().is_empty()) {
244	            let kind_paths = cfg.kinds.iter_mut().flat_map(|k| k.paths.iter_mut());
245	            for p in cfg.source.paths.iter_mut().chain(kind_paths) {
246	                if p != "-" && Path::new(p).is_relative() {
247	                    *p = dir.join(&*p).display().to_string();
248	                }
249	            }
250	            if let Some(p) = &mut cfg.memory.path
251	                && Path::new(p).is_relative()
252	                && !p.starts_with('~')
253	            {
254	                *p = dir.join(&*p).display().to_string();
255	            }
256	        }
257	        cfg.validate()?;
258	        Ok(cfg)
259	    }
260	
261	    pub fn validate(&self) -> Result<()> {
262	        validate_fields(&self.fields)?;
263	        let mut names = std::collections::HashSet::new();
264	        for k in &self.kinds {
265	            if k.name.is_empty() || kind_name(&k.name) != k.name {
266	                bail!("kind name {:?} must be lowercase letters, digits, `_` or `-`", k.name);
267	            }
268	            if !names.insert(k.name.as_str()) {
269	                bail!("two kinds are named {:?}", k.name);
270	            }
271	            validate_fields(&k.fields).with_context(|| format!("kind {:?}", k.name))?;
272	        }
273	        if !(self.rank.title_weight.is_finite() && self.rank.title_weight >= 0.0) {
274	            bail!("`rank.title_weight` must be a non-negative number");
275	        }
276	        for b in &self.rank.boost {
277	            if b.field.is_empty() || !(b.weight.is_finite() && b.weight > -1.0) {
278	                bail!("each [[rank.boost]] needs a `field` and a `weight` above -1");
279	            }
280	        }
281	        let m = &self.memory;
282	        if !(50..=20_000).contains(&m.budget) || !(50..=20_000).contains(&m.briefing_budget) {
283	            bail!("`memory.budget` and `memory.briefing_budget` must be between 50 and 20000 tokens");
284	        }
285	        if !(40..=4000).contains(&m.max_chars) {
286	            bail!("`memory.max_chars` must be between 40 and 4000");
287	        }
288	        for (kind, days) in &m.half_life {
289	            if crate::memory::Kind::parse(kind).is_none() || !(days.is_finite() && *days >= 0.0) {
290	                bail!(
291	                    "`memory.half_life.{kind}`: kind must be one of {} and days >= 0",
292	                    crate::memory::Kind::NAMES
293	                );
294	            }
295	        }
296	        Ok(())
297	    }
298	
299	    pub fn to_toml(&self) -> String {
300	        toml::to_string(self).unwrap_or_default()
301	    }
302	}
303	
304	fn validate_fields(f: &Fields) -> Result<()> {
305	    let all = f.id.iter().chain(&f.title).chain(&f.text).chain(&f.group).chain(&f.group_name);
306	    for path in all.chain(&f.date).chain(&f.filters).chain(&f.display) {
307	        if path.trim().is_empty() {
308	            bail!("empty field path in the mapping");
309	        }
310	    }
311	    if f.group_name.is_some() && f.group.is_none() {
312	        bail!("`group_name` needs `group`");
313	    }
314	    Ok(())
315	}
316	
317	/// Plural of a configured noun, for headers like "33 log lines".
318	pub fn plural(noun: &str) -> String {
319	    if noun.ends_with('s') || noun.ends_with("data") {
320	        noun.to_string()
321	    } else if let Some(stem) = noun.strip_suffix('y').filter(|s| !s.ends_with(['a', 'e', 'o', 'u'])) {
322	        format!("{stem}ies")
323	    } else {
324	        format!("{noun}s")
325	    }
326	}
327	
328	/// Mapping overrides from the command line, applied on top of the config.
329	#[derive(Debug, Clone, Default, clap::Args)]
330	pub struct FieldFlags {
331	    /// Config file [default: ./leviathan.toml when present]
332	    #[arg(long, short = 'c', env = "LEVIATHAN_CONFIG")]
333	    pub config: Option<std::path::PathBuf>,
334	    /// Unique id field
335	    #[arg(long, value_name = "PATH")]
336	    pub id: Option<String>,
337	    /// Title field(s); first present wins
338	    #[arg(long, value_name = "PATH", value_delimiter = ',')]
339	    pub title: Vec<String>,
340	    /// Searched text fields (default: every string)
341	    #[arg(long, value_name = "PATH", value_delimiter = ',')]
342	    pub text: Vec<String>,
343	    /// Group field for scoped search
344	    #[arg(long, value_name = "PATH")]
345	    pub group: Option<String>,
346	    /// Human-readable group name field
347	    #[arg(long, value_name = "PATH")]
348	    pub group_name: Option<String>,
349	    /// Date field(s); first present wins
350	    #[arg(long, value_name = "PATH", value_delimiter = ',')]
351	    pub date: Vec<String>,
352	    /// Exact-match filter fields
353	    #[arg(long = "filter", value_name = "PATH", value_delimiter = ',')]
354	    pub filters: Vec<String>,
355	    /// Fields shown on result cards
356	    #[arg(long, value_name = "PATH", value_delimiter = ',')]
357	    pub display: Vec<String>,
358	    /// Placeholder values treated as missing
359	    #[arg(long = "empty-value", value_name = "TEXT")]
360	    pub empty_values: Vec<String>,
361	    /// Input format
362	    #[arg(long, value_enum)]
363	    pub format: Option<Format>,
364	    /// SQL query for SQLite sources
365	    #[arg(long)]
366	    pub sql: Option<String>,
367	}
368	
369	impl FieldFlags {
370	    /// The config file to use: explicit, else `./leviathan.toml` if it exists.
371	    pub fn config_path(&self) -> Option<std::path::PathBuf> {
372	        self.config.clone().or_else(|| {
373	            let default = Path::new(DEFAULT_FILE);
374	            default.exists().then(|| default.to_path_buf())
375	        })
376	    }
377	
378	    pub fn is_empty(&self) -> bool {
379	        self.id.is_none()
380	            && self.title.is_empty()
381	            && self.text.is_empty()
382	            && self.group.is_none()
383	            && self.group_name.is_none()
384	            && self.date.is_empty()
385	            && self.filters.is_empty()
386	            && self.display.is_empty()
387	            && self.empty_values.is_empty()
388	    }
389	
390	    pub fn apply(&self, cfg: &mut Config) {
391	        let f = &mut cfg.fields;
392	        if self.id.is_some() {
393	            f.id.clone_from(&self.id);
394	        }
395	        if self.group.is_some() {
396	            f.group.clone_from(&self.group);
397	        }
398	        if self.group_name.is_some() {
399	            f.group_name.clone_from(&self.group_name);
400	        }
401	        for (dst, src) in [
402	            (&mut f.title, &self.title),
403	            (&mut f.text, &self.text),
404	            (&mut f.date, &self.date),
405	            (&mut f.filters, &self.filters),
406	            (&mut f.display, &self.display),
407	            (&mut f.empty_values, &self.empty_values),
408	        ] {
409	            if !src.is_empty() {
410	                dst.clone_from(src);
411	            }
412	        }
413	        if let Some(format) = self.format {
414	            cfg.source.format = format;
415	        }
416	        if self.sql.is_some() {
417	            cfg.source.sql.clone_from(&self.sql);
418	        }
419	    }
420	}
421	
422	#[cfg(test)]
423	mod tests {
424	    use super::*;
425	
426	    #[test]
427	    fn parses_one_or_many_and_defaults() {
428	        let cfg: Config = toml::from_str(
429	            r#"
430	            [fields]
431	            id = "id"
432	            title = "subject"
433	            date = ["closed", "opened"]
434	            [[rank.boost]]
435	            field = "resolution"
436	            weight = 0.15
437	            "#,
438	        )
439	        .unwrap();
440	        assert_eq!(cfg.fields.title, ["subject"]);
441	        assert_eq!(cfg.fields.date, ["closed", "opened"]);
442	        assert_eq!(cfg.about.record, "record");
443	        assert_eq!(cfg.rank.title_weight, 2.0);
444	        assert_eq!(cfg.rank.boost[0].field, ["resolution"]);
445	    }
446	
447	    #[test]
448	    fn rejects_unknown_keys() {
449	        assert!(toml::from_str::<Config>("[fields]\nidd = \"x\"").is_err());
450	    }
451	
452	    #[test]
453	    fn plurals() {
454	        assert_eq!(plural("log line"), "log lines");
455	        assert_eq!(plural("entry"), "entries");
456	        assert_eq!(plural("day"), "days");
457	        assert_eq!(plural("logs"), "logs");
458	    }
459	}
