324	            State::Superseded => {
325	                head.push_str(&format!(
326	                    " · SUPERSEDED {}",
327	                    day(self.valid_to.as_deref().unwrap_or_default())
328	                ));
329	            }
330	            State::Forgotten => {
331	                head.push_str(&format!(
332	                    " · FORGOTTEN {}",
333	                    day(self.deleted_at.as_deref().unwrap_or_default())
334	                ));
335	            }
336	            State::Expired => head.push_str(" · EXPIRED"),
337	        }
338	        head.push(']');
339	        let mut out = head;
340	        if show_ns {
341	            out.push_str(&format!(" {}:", self.ns));
342	        }
343	        match (&self.subject, &self.key) {
344	            (Some(s), Some(k)) => out.push_str(&format!(" {s} · {k}:")),
345	            (Some(s), None) => out.push_str(&format!(" {s}:")),
346	            (None, Some(k)) => out.push_str(&format!(" {k}:")),
347	            (None, None) => {}
348	        }
349	        out.push(' ');
350	        out.push_str(&self.text);
351	        let mut meta = vec![day(&self.valid_from).to_string()];
352	        if let Some(s) = &self.source {
353	            meta.push(s.clone());
354	        }
355	        if self.pinned {
356	            meta.push("pinned".into());
357	        }
358	        if !self.refs.is_empty() {
359	            meta.push(format!("refs {}", self.refs.join(", ")));
360	        }
361	        meta.push(self.id.clone());
362	        out.push_str(&format!(" ({})", meta.join(" · ")));
363	        out
364	    }
365	}
