540	    /// Namespaces to read: an explicit comma list, `*` for every namespace,
541	    /// or the configured `read` list.
542	    pub fn read_namespaces(&self, ns: Option<&str>) -> Result<Vec<String>> {
543	        let Some(raw) = ns.map(str::trim).filter(|s| !s.is_empty()) else {
544	            return Ok(self.settings.read.clone());
545	        };
546	        if raw == "*" {
547	            let mut stmt = self.conn.prepare_cached("SELECT DISTINCT ns FROM memories ORDER BY ns")?;
548	            let all = stmt.query_map([], |r| r.get(0))?.collect::<rusqlite::Result<Vec<String>>>()?;
549	            return Ok(if all.is_empty() { self.settings.read.clone() } else { all });
550	        }
551	        raw.split(',').map(|n| guard::namespace(n).map_err(Into::into)).collect()
552	    }
