592	    /// Newest first. `all` includes superseded, forgotten and expired rows.
593	    pub fn list(
594	        &self,
595	        ns: &[String],
596	        kind: Option<Kind>,
597	        subject: Option<&str>,
598	        all: bool,
599	        limit: usize,
600	    ) -> Result<Vec<MemoryRow>> {
601	        let mut sql = format!("SELECT {COLUMNS} FROM memories WHERE ns IN ({})", placeholders(ns.len(), 1));
602	        let mut args: Vec<rusqlite::types::Value> = ns.iter().cloned().map(Into::into).collect();
603	        if !all {
604	            args.push(now().into());
605	            sql.push_str(&format!(
606	                " AND valid_to IS NULL AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?{})",
607	                args.len()
608	            ));
609	        }
610	        if let Some(k) = kind {
611	            args.push(k.as_str().to_string().into());
612	            sql.push_str(&format!(" AND kind = ?{}", args.len()));
613	        }
614	        if let Some(s) = subject {
615	            args.push(normalize_name(s).into());
616	            sql.push_str(&format!(" AND subject_norm = ?{}", args.len()));
617	        }
618	        args.push((limit.clamp(1, 10_000) as i64).into());
619	        sql.push_str(&format!(" ORDER BY updated_at DESC, rowid DESC LIMIT ?{}", args.len()));
620	        let mut stmt = self.conn.prepare(&sql)?;
621	        Ok(stmt.query_map(rusqlite::params_from_iter(args), row)?.collect::<rusqlite::Result<_>>()?)
622	    }
