624	    pub fn stats(&self) -> Result<MemoryStats> {
625	        let now = now();
626	        let one = |sql: &str| -> Result<i64> { Ok(self.conn.query_row(sql, [&now], |r| r.get(0))?) };
627	        let current_sql =
628	            "valid_to IS NULL AND deleted_at IS NULL AND (expires_at IS NULL OR expires_at > ?1)";
629	        let pairs = |sql: &str| -> Result<Vec<(String, i64)>> {
630	            let mut stmt = self.conn.prepare(sql)?;
631	            Ok(stmt.query_map([&now], |r| Ok((r.get(0)?, r.get(1)?)))?.collect::<rusqlite::Result<_>>()?)
632	        };
633	        let version: String =
634	            self.conn.query_row("SELECT value FROM meta WHERE key = 'schema_version'", [], |r| r.get(0))?;
635	        Ok(MemoryStats {
636	            path: self.path.clone(),
637	            bytes: std::fs::metadata(&self.path).map(|m| m.len()).unwrap_or(0),
638	            schema_version: version,
639	            namespace: self.settings.namespace.clone(),
640	            read: self.settings.read.clone(),
641	            current: one(&format!("SELECT COUNT(*) FROM memories WHERE {current_sql}"))?,
642	            superseded: one(
643	                "SELECT COUNT(*) FROM memories WHERE valid_to IS NOT NULL AND deleted_at IS NULL AND ?1 = ?1",
644	            )?,
645	            forgotten: one("SELECT COUNT(*) FROM memories WHERE deleted_at IS NOT NULL AND ?1 = ?1")?,
646	            expired: one(
647	                "SELECT COUNT(*) FROM memories WHERE valid_to IS NULL AND deleted_at IS NULL AND expires_at <= ?1",
648	            )?,
649	            by_kind: pairs(&format!(
650	                "SELECT kind, COUNT(*) FROM memories WHERE {current_sql} GROUP BY kind ORDER BY 2 DESC, 1"
651	            ))?,
652	            by_namespace: pairs(&format!(
653	                "SELECT ns, COUNT(*) FROM memories WHERE {current_sql} GROUP BY ns ORDER BY 2 DESC, 1"
654	            ))?,
655	            top_subjects: pairs(&format!(
656	                "SELECT subject, COUNT(*) FROM memories WHERE {current_sql} AND subject IS NOT NULL \
657	                 GROUP BY subject_norm ORDER BY 2 DESC, 1 LIMIT 10"
658	            ))?,
659	            newest: self
660	                .conn
661	                .query_row("SELECT MAX(updated_at) FROM memories", [], |r| r.get(0))
662	                .optional()?
663	                .flatten(),
664	        })
665	    }
